#pragma once
#include "../film_native_contact/CoupledContactStep.h"
#include "ClosestPrimitive.h"
#include <sstream>
#include <iomanip>
namespace regrip_film_sphere {
using namespace regrip_film_native;
// New model: fixed material support from the native predictor, but EXACT
// current sphere gap/normal and its mechanical tangent. NOT native surface
// contact equivalence, continuous contact area, CCD, friction or free bodies.
struct SphereStep {
 const CoupledContactStep&base;Eigen::Vector3d center;double radius;bool closestPrimitive=false,releaseActiveSet=false,sqpMerit=false;
 struct Column{int index;Eigen::Vector3d value;};
 struct Stencil{std::vector<double>weights;Eigen::Vector3d initial;std::vector<Column>columns;std::vector<unsigned>nodes;};
 std::vector<Stencil>stencils;
 struct Radial{double gap;Eigen::Vector3d normal;Eigen::Matrix3d hessian;};
 static Radial radial(const Eigen::Vector3d&p,const Eigen::Vector3d&c,double radius){auto r=(p-c).eval();double length=r.norm();if(!(length>0)||!std::isfinite(length))throw std::runtime_error("undefined sphere normal at center;no epsilon regularization");Eigen::Vector3d n=r/length;return {length-radius,n,(Eigen::Matrix3d::Identity()-n*n.transpose())/length};}
 SphereStep(const CoupledContactStep&step,Point c,double r,bool closest=false):base(step),center(c[0],c[1],c[2]),radius(r),closestPrimitive(closest){
  if(!(r>0))throw std::invalid_argument("positive sphere radius");auto rest=base.mechanics.model.rest();
  for(const auto&plane:base.planes){Stencil s;s.nodes=plane.support;if(s.nodes.empty())for(unsigned i=0;i<plane.J.size();++i)if(dot(plane.J[i],plane.J[i])>0)s.nodes.push_back(i);if(closestPrimitive&&(s.nodes.empty()||s.nodes.size()>3))throw std::runtime_error("native primitive support must contain1..3 vertices");s.weights.resize(rest.size());s.initial.setZero();Eigen::Vector3d direction=Eigen::Vector3d::Zero();for(auto j:plane.J)direction+=Eigen::Vector3d(j[0],j[1],j[2]);double length=direction.norm();if(!(length>0))throw std::runtime_error("zero native support direction");direction/=length;double sum=0;
   for(unsigned i=0;i<rest.size();++i){Eigen::Vector3d j(plane.J[i][0],plane.J[i][1],plane.J[i][2]);s.weights[i]=j.dot(direction);if(s.weights[i]<0||(j-s.weights[i]*direction).norm()>1e-10)throw std::runtime_error("nonpositive/nonparallel scalar native support");sum+=s.weights[i];}
   if(!(sum>0))throw std::runtime_error("empty material support");Eigen::MatrixXd P=Eigen::MatrixXd::Zero(3,base.mechanics.freeSize);
   for(unsigned i=0;i<rest.size();++i){s.weights[i]/=sum;for(unsigned d=0;d<3;++d){s.initial(d)+=s.weights[i]*(rest[i][d]+base.mechanics.previous[i][d]);unsigned a=3*i+d;if(base.mechanics.index[a]>=0)P(d,base.mechanics.index[a])+=s.weights[i]*base.mechanics.weight[a];}}
   for(int i=0;i<P.cols();++i)if(P.col(i).squaredNorm()>0)s.columns.push_back({i,P.col(i)});stencils.push_back(std::move(s));
  }
 }
 struct Geometry{Eigen::VectorXd gap;Eigen::MatrixXd C,H;};
 void dumpFailure(std::ostream&out,const std::vector<Point>&initial,const Eigen::VectorXd&trial,const Eigen::VectorXd&lambda)const{std::ostringstream buffer;buffer<<std::setprecision(17)<<"\nSPHERE_FAILURE_V2 "<<base.mechanics.model.nx<<' '<<base.mechanics.model.guideIntervals<<' '<<base.mechanics.model.guideOffset<<' '<<base.mechanics.model.bondK<<' '<<base.mechanics.model.rootGuideSecondOrder<<' '<<base.mechanics.h<<' '<<base.mechanics.damping<<' '<<base.mechanics.T<<' '<<center.transpose()<<' '<<radius<<' '<<closestPrimitive<<' '<<base.planes.size()<<'\n';buffer<<"MASS ";for(double m:base.mechanics.mass)buffer<<m<<' ';buffer<<'\n';auto points=[&](const char*name,const std::vector<Point>&values){buffer<<name<<' ';for(auto p:values)for(double value:p)buffer<<value<<' ';buffer<<'\n';};points("PREVIOUS_U",base.mechanics.previous);points("PREVIOUS_V",base.mechanics.previousVelocity);points("INITIAL_V",initial);points("REJECTED_V",base.mechanics.expand(trial));for(const auto&p:base.planes){buffer<<"PLANE "<<p.target<<' '<<p.lambda<<' '<<p.row<<' ';for(auto j:p.J)for(double value:j)buffer<<value<<' ';buffer<<" SUPPORT "<<p.support.size()<<' ';for(unsigned node:p.support)buffer<<node<<' ';buffer<<'\n';}buffer<<"TRIAL_LAMBDA "<<lambda.transpose()<<'\n';buffer<<"END_SPHERE_FAILURE\n";out<<buffer.str();}
 Geometry geometry(const Eigen::VectorXd&y,const Eigen::VectorXd&lambda,bool hessian=true)const{Geometry out;unsigned m=stencils.size();out.gap.resize(m);out.C=Eigen::MatrixXd::Zero(y.size(),m);if(hessian)out.H=Eigen::MatrixXd::Zero(y.size(),y.size());
  for(unsigned k=0;k<m;++k){if(closestPrimitive){auto rest=base.mechanics.model.rest();std::vector<Point>positions;for(unsigned node:stencils[k].nodes){Point p;for(unsigned d=0;d<3;++d){unsigned a=3*node+d;double v=base.mechanics.index[a]<0?0:base.mechanics.weight[a]*y(base.mechanics.index[a]);p[d]=rest[node][d]+base.mechanics.previous[node][d]+base.mechanics.h*v;}positions.push_back(p);}auto e=ClosestPrimitive::evaluate(positions,{center[0],center[1],center[2]},radius);out.gap(k)=e.gap.v;for(unsigned a=0;a<3*positions.size();++a){unsigned ga=3*stencils[k].nodes[a/3]+a%3;int ia=base.mechanics.index[ga];if(ia<0)continue;out.C(ia,k)+=base.mechanics.weight[ga]*e.gap.g[a];if(hessian)for(unsigned b=0;b<3*positions.size();++b){unsigned gb=3*stencils[k].nodes[b/3]+b%3;int ib=base.mechanics.index[gb];if(ib>=0)out.H(ia,ib)+=base.mechanics.h*lambda(k)*base.mechanics.weight[ga]*base.mechanics.weight[gb]*e.gap.h[N*a+b];}}continue;}auto p=stencils[k].initial;for(const auto&column:stencils[k].columns)p+=base.mechanics.h*column.value*y(column.index);auto e=radial(p,center,radius);out.gap(k)=e.gap;for(const auto&a:stencils[k].columns){out.C(a.index,k)=a.value.dot(e.normal);if(hessian)for(const auto&b:stencils[k].columns)out.H(a.index,b.index)+=base.mechanics.h*lambda(k)*a.value.dot(e.hessian*b.value);}}
  return out;
 }
 CoupledContactStep::Result solve(const std::vector<Point>&initial,std::ostream*trace=nullptr)const{auto y=base.mechanics.pack(initial);Eigen::VectorXd lambda(base.planes.size());for(unsigned k=0;k<base.planes.size();++k)lambda(k)=base.planes[k].lambda;double first=-1;unsigned evaluations=0,reuses=0;std::optional<CoupledPlaneStep::Evaluation>saved;Eigen::VectorXd savedY;
  for(unsigned iteration=0;iteration<30;++iteration){CoupledPlaneStep::Evaluation e;if(base.reuseAcceptedEvaluation&&saved&&savedY.size()==y.size()&&std::memcmp(savedY.data(),y.data(),sizeof(double)*y.size())==0){e=std::move(*saved);saved.reset();++reuses;}else{e=base.mechanics.evaluate(y);++evaluations;}auto g=geometry(y,lambda);double residual=(e.gradient-g.C*lambda).norm(),gap=CoupledContactStep::gapError(g.gap,lambda);if(first<0)first=residual;if(trace)*trace<<"sphere_iteration "<<iteration<<" residual "<<residual<<" gap "<<gap<<'\n';
   if(residual<=std::max(1e-15,first*1e-7)&&gap<=1e-10){CoupledContactStep::Result result;result.velocity=base.mechanics.expand(y);result.displacement=base.mechanics.previous;for(unsigned i=0;i<result.velocity.size();++i)for(unsigned d=0;d<3;++d)result.displacement[i][d]+=base.mechanics.h*result.velocity[i][d];result.lambda=lambda;result.residual=residual;result.gap=gap;result.iterations=iteration;result.evaluations=evaluations;result.acceptedReuses=reuses;return result;}
   Eigen::MatrixXd H=e.tangent-g.H;Eigen::LDLT<Eigen::MatrixXd>factor(H);if(factor.info()!=Eigen::Success||factor.vectorD().minCoeff()<=0){if(trace){Eigen::LDLT<Eigen::MatrixXd>mechanicalFactor(e.tangent);*trace<<"tangent_rejected rows "<<stencils.size()<<" lagrangian_status "<<factor.info()<<" mechanical_status "<<mechanicalFactor.info();if(factor.info()==Eigen::Success)*trace<<" lagrangian_minD "<<factor.vectorD().minCoeff();if(mechanicalFactor.info()==Eigen::Success)*trace<<" mechanical_minD "<<mechanicalFactor.vectorD().minCoeff();*trace<<'\n';dumpFailure(*trace,initial,y,lambda);}throw std::runtime_error("nonpositive TRUE sphere Lagrangian tangent;no regularization");}Eigen::VectorXd inverseG=factor.solve(e.gradient);Eigen::MatrixXd inverseC=factor.solve(g.C),W=base.mechanics.h*g.C.transpose()*inverseC;Eigen::VectorXd d=g.gap-base.mechanics.h*g.C.transpose()*inverseG;auto next=CoupledContactStep::dual(W,d,lambda);Eigen::VectorXd increment=-inverseG+inverseC*next;double oldMerit=0;
   auto merit=[&](const Eigen::VectorXd&grad,const Geometry&geometry,const Eigen::VectorXd&l){double squared=(grad-geometry.C*l).squaredNorm();for(int k=0;k<l.size();++k){if(!(W(k,k)>0))throw std::runtime_error("degenerate sphere compliance");double value=std::min(l(k),geometry.gap(k)/W(k,k));squared+=value*value;}return std::sqrt(squared);};oldMerit=merit(e.gradient,g,lambda);bool accepted=false;double alpha=1;
   for(unsigned trial=0;trial<16;++trial){Eigen::VectorXd candidateY=y+alpha*increment,candidateLambda=lambda+alpha*(next-lambda);if(releaseActiveSet)for(int k=0;k<next.size();++k)if(next(k)==0)candidateLambda(k)=0;auto candidate=base.mechanics.evaluate(candidateY);++evaluations;auto candidateGeometry=geometry(candidateY,candidateLambda,false);double value=merit(candidate.gradient,candidateGeometry,candidateLambda),directional=alpha*e.gradient.dot(increment),roundoff=64*std::numeric_limits<double>::epsilon()*std::max(std::abs(e.phi),std::abs(candidate.phi));bool feasible=(g.gap.size()==0||g.gap.minCoeff()>=-1e-10)&&(candidateGeometry.gap.size()==0||candidateGeometry.gap.minCoeff()>=-1e-10);bool energy=base.potentialMerit&&feasible&&directional < -roundoff&&candidate.phi<=e.phi+1e-4*directional;
    // Exact L1 inequality merit is a SOLVER globalization, not contact compliance.
    // Mechanical multiplier is lambda/h because dg/dy=h*C^T. The accepted
    // residual/gap gates and forces remain identical to the original model.
    bool sqp=false;if(sqpMerit){double rho=next.size()?2*std::max(next.maxCoeff(),lambda.maxCoeff())/base.mechanics.h:0;double oldPenalty=0,newPenalty=0,slope=e.gradient.dot(increment);Eigen::VectorXd gapDirection=base.mechanics.h*g.C.transpose()*increment;for(int k=0;k<g.gap.size();++k){oldPenalty+=std::max(-g.gap(k),0.);newPenalty+=std::max(-candidateGeometry.gap(k),0.);if(g.gap(k)<0)slope-=rho*gapDirection(k);else if(g.gap(k)==0)slope+=rho*std::max(-gapDirection(k),0.);}double bound=64*std::numeric_limits<double>::epsilon()*std::max(std::abs(e.phi)+rho*oldPenalty,std::abs(candidate.phi)+rho*newPenalty);sqp=alpha*slope < -bound&&candidate.phi+rho*newPenalty<=e.phi+rho*oldPenalty+1e-4*alpha*slope;}
    if(value<=(1-1e-4*alpha)*oldMerit||energy||sqp){y=std::move(candidateY);lambda=std::move(candidateLambda);if(base.reuseAcceptedEvaluation){savedY=y;saved=std::move(candidate);}accepted=true;break;}alpha*=.5;
   }if(!accepted){if(trace)dumpFailure(*trace,initial,y,lambda);throw std::runtime_error("sphere residual/potential line search failed");}
  }if(trace)dumpFailure(*trace,initial,y,lambda);throw std::runtime_error("sphere nonlinear Newton budget");
 }
 std::vector<Point>nodal(const std::vector<Point>&u,const Eigen::VectorXd&lambda,std::vector<Point>&normals,std::vector<Point>*locations=nullptr)const{auto rest=base.mechanics.model.rest();std::vector<Point>impulse(rest.size());normals.resize(stencils.size());if(locations)locations->resize(stencils.size());for(unsigned k=0;k<stencils.size();++k){if(closestPrimitive){std::vector<Point>positions;for(unsigned node:stencils[k].nodes)positions.push_back(add(rest[node],u[node]));auto e=ClosestPrimitive::evaluate(positions,{center[0],center[1],center[2]},radius);Eigen::Vector3d p(e.point[0].v,e.point[1].v,e.point[2].v);auto radialValue=radial(p,center,radius);for(unsigned d=0;d<3;++d){normals[k][d]=radialValue.normal(d);if(locations)(*locations)[k][d]=p(d);}for(unsigned a=0;a<3*positions.size();++a)impulse[stencils[k].nodes[a/3]][a%3]+=lambda(k)*e.gap.g[a];continue;}Eigen::Vector3d p=Eigen::Vector3d::Zero();for(unsigned i=0;i<rest.size();++i)for(unsigned d=0;d<3;++d)p(d)+=stencils[k].weights[i]*(rest[i][d]+u[i][d]);auto e=radial(p,center,radius);for(unsigned d=0;d<3;++d){normals[k][d]=e.normal(d);if(locations)(*locations)[k][d]=p(d);for(unsigned i=0;i<rest.size();++i)impulse[i][d]+=lambda(k)*stencils[k].weights[i]*e.normal(d);}}return impulse;}
};
}
